import * as React from "react";
import { cn } from "@/lib/utils";

export interface ButtonRowProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Minimum width each button keeps before the row wraps to a stack.
   * Once two buttons can no longer sit side by side at this floor they wrap,
   * each taking the full row width on its own line. Default `140px`.
   */
  minItemWidth?: string;
}

/**
 * Lays buttons in a horizontal row that WRAPS to a stack when they no longer
 * fit. Each child grows equally (`flex-1`) down to a `minItemWidth` floor; below
 * that the buttons stack one beneath the other, each full width. Pair with the
 * Button component, whose labels wrap to two lines rather than overflow -- so a
 * single long (e.g. translated) label breaks inside its pill while the row
 * itself only stacks when the buttons genuinely cannot share a line.
 *
 * Drop-in replacement for the hand-rolled `flex flex-wrap gap-3` +
 * `flex-1 min-w-[140px]` idiom: just wrap the buttons. Tune the wrap point for
 * the whole row with `minItemWidth` (raise it to make the buttons stack sooner
 * so labels stay on one line).
 *
 * @example
 * ```tsx
 * <ButtonRow>
 *   <Button variant="outline" onClick={onImport}>{t('settings.import')}</Button>
 *   <Button variant="outline" onClick={onExport}>{t('settings.export')}</Button>
 * </ButtonRow>
 * ```
 */
const ButtonRow = React.forwardRef<HTMLDivElement, ButtonRowProps>(
  ({ className, children, minItemWidth = "140px", ...props }, ref) => (
    <div ref={ref} className={cn("flex flex-wrap gap-3", className)} {...props}>
      {React.Children.map(children, (child) =>
        React.isValidElement(child)
          ? React.cloneElement(
              child as React.ReactElement<{ className?: string; style?: React.CSSProperties }>,
              {
                className: cn("flex-1", (child.props as { className?: string }).className),
                style: {
                  minWidth: minItemWidth,
                  ...((child.props as { style?: React.CSSProperties }).style ?? {}),
                },
              }
            )
          : child
      )}
    </div>
  )
);
ButtonRow.displayName = "ButtonRow";

export { ButtonRow };
